      "生活不动声色，我也懒得声张。",
      "心静不下来的时候，就让香先静。",
      "大不了从头再来，反正也没输过什么。",
      "我不是躺平，是换个姿势蓄力。",
      "世界越吵，越要留一间自己的书房。",
      "情绪上头的时候，先把水烧上。"
