        "scene": "互动提问场",
        "text": "深夜灵魂拷问：如果明天突然不用上班，你最想干嘛？我先来——睡到自然醒，逛早市买花，下午盘串喝茶，晚上撸串小酌。评论区交出你的答案，让我看看谁的过法最野？"
