    "dailyplay": [
      {
        "scene": "喝酒微醺场",
        "text": "散伙的酒局没去，一个人在家倒了半杯。窗外下着雨，杯子里晃着灯光。成年人的崩溃很安静，成年人的自愈也是——两口下肚，没说出口的委屈就先寄存在微醺里吧。生活不易，但酒是真的解千愁。"
      },
      {
        "scene": "深夜宵夜场",
        "text": "十二点的大排档，才是这座城市的真心话现场。烤串滋滋响，冰啤冒着气，白天的体面全卸在塑料凳上。都说宵夜伤身，可不吃才伤心。罪恶感先放一边，快乐要紧，明天的事明天再愧疚。"
      },
      {
        "scene": "干饭吃货场",
        "text": "谁再跟我说「随便吃点」我跟谁急。火锅刚开，毛肚七上八下，人间烟火气最抚凡人心。工作可以糊弄，饭绝对不行——吃是人生第一要义，剩下的都往后稍稍，天大的事也得吃饱了再说。"
      },
      {
        "scene": "闲逛放风场",
        "text": "没有目的地的溜达，才是真正的自由。逛了两条街什么都没买，看了会儿别人打台球，又蹲在路边看了十分钟晚霞。一事无成的下午，却觉得赚到了。松弛感这东西，原来根本不要钱。"
      },
      {
        "scene": "居家百态场",
        "text": "周末最高级的享受：手机静音，沙发瘫平，茶壶咕嘟着，一炉香慢慢烧。不用营业不用寒暄，谁的消息都不急着回。这个不用社交的舒适圈，我能一直待到天荒地老，谁劝都不好使。"
      },
      {
        "scene": "打工人发疯场",
        "text": "早高峰地铁被挤成一张纸，工位坐下那一刻突然想笑。精神状态？良好，非常好，好到想在会议室表演一个原地消失。没事，再忍忍，忍到发工资那天，我又是一条好汉，工牌一挂继续冲。"
      },
      {
        "scene": "生活翻车场",
        "text": "兴致勃勃复刻网红菜，成品像案发现场。锅糊了，烟感器响了，外卖还拿错了邻居的。朋友问我今晚吃啥，我说：吃一堑长一智。真实到没朋友的一天，但笑着笑着，也就这么过去了。"
      },
      {
        "scene": "互动提问场",
        "text": "深夜灵魂拷问：如果明天突然不用上班，你最想干嘛？我先来——睡到自然醒，逛早市买花，下午盘串喝茶，晚上撸串小酌。评论区交出你的答案，让我看看谁的过法最野？"
      }
    ]
